"""Generate a SolidWorks VBA macro that updates global variables"""

from __future__ import annotations

from paramfabric.core.graph import ParameterGraph


def generate_solidworks_macro(graph: ParameterGraph) -> str:
    """Create a macro for a currently open SolidWorks document"""
    lines = [
        "' Generated by Paramfabric; run against an open SolidWorks part/assembly.",
        "Option Explicit",
        "Dim swApp As Object",
        "Dim swModel As Object",
        "Dim swEquationMgr As Object",
        "Dim equationIndex As Long",
        "Dim updateError As Long",
        "Sub main()",
        "    Set swApp = Application.SldWorks",
        "    Set swModel = swApp.ActiveDoc",
        "    If swModel Is Nothing Then Err.Raise vbObjectError + 1, , \"Open a SolidWorks document first.\"",
        "    Set swEquationMgr = swModel.GetEquationMgr",
    ]
    for parameter in graph.fabric.parameters:
        if parameter.type in {"str", "bool"}:
            continue
        name = parameter.name
        value = format(float(graph.value(name).magnitude), ".15g")
        equation = f'"{name}" = {value}{parameter.unit}'
        lines.extend(
            (
                f"    ' Value in {parameter.unit}",
                f"    equationIndex = swEquationMgr.GetCount",
                f"    swEquationMgr.Add2 equationIndex, {vba_string(equation)}, True",
            )
        )
    lines.extend(("    updateError = swModel.EditRebuild3", "End Sub", ""))
    return "\n".join(lines)


def vba_string(value: str) -> str:
    return '"' + value.replace('"', '""') + '"'
